import { describe, it, expect } from "bun:test";
import { isLongTerm, isShortTerm, longTermStartSecs } from "../../src/rules/holding-period";
const utc = (iso: string) => Math.floor(Date.parse(iso) / 1000);
const DAY = 86400;
describe("isLongTerm — §1222 / Pub 550 calendar rule", () => {
    it("a hold spanning a LEAP DAY is still SHORT-term on its anniversary (366 elapsed days)", () => {
        const acquired = utc("2024-01-15T12:00:00Z");
        const anniversary = utc("2025-01-15T12:00:00Z");
        expect((anniversary - acquired) / DAY).toBe(366);
        expect(isLongTerm(acquired, anniversary)).toBe(false);
        expect(isLongTerm(acquired, utc("2025-01-16T00:00:00Z"))).toBe(true);
    });
    it("an anniversary-day sale LATER in the day is short-term (no leap year needed)", () => {
        const acquired = utc("2023-03-01T09:00:00Z");
        const sameDayLater = utc("2024-03-01T15:00:00Z");
        expect(sameDayLater - acquired).toBeGreaterThan(365 * DAY);
        expect(isLongTerm(acquired, sameDayLater)).toBe(false);
    });
    it("an anniversary-day sale EARLIER in the day is short-term too (both sides of the boundary)", () => {
        const acquired = utc("2023-03-01T15:00:00Z");
        expect(isLongTerm(acquired, utc("2024-03-01T09:00:00Z"))).toBe(false);
        expect(isLongTerm(acquired, utc("2024-03-02T00:00:00Z"))).toBe(true);
    });
    it("Pub 550's own example: Sep 3 → Sep 3 short, Sep 4 long", () => {
        const acquired = utc("2022-09-03T18:30:00Z");
        expect(isLongTerm(acquired, utc("2023-09-03T23:59:59Z"))).toBe(false);
        expect(isLongTerm(acquired, utc("2023-09-04T00:00:00Z"))).toBe(true);
    });
    it("a Feb-29 acquisition turns long-term on Mar 1 of the following year", () => {
        const acquired = utc("2024-02-29T10:00:00Z");
        expect(isLongTerm(acquired, utc("2025-02-28T23:59:59Z"))).toBe(false);
        expect(isLongTerm(acquired, utc("2025-03-01T00:00:00Z"))).toBe(true);
    });
    it("a Dec-31 acquisition rolls the LT start into the next calendar year", () => {
        expect(longTermStartSecs(utc("2024-12-31T05:00:00Z"))).toBe(utc("2026-01-01T00:00:00Z"));
    });
    it("isShortTerm is the exact inverse", () => {
        const acquired = utc("2024-01-15T12:00:00Z");
        expect(isShortTerm(acquired, utc("2025-01-15T12:00:00Z"))).toBe(true);
        expect(isShortTerm(acquired, utc("2025-01-16T12:00:00Z"))).toBe(false);
    });
    it("non-finite inputs read short-term (conservative), never long", () => {
        expect(isLongTerm(NaN, utc("2025-01-15T00:00:00Z"))).toBe(false);
        expect(isLongTerm(utc("2020-01-15T00:00:00Z"), NaN)).toBe(false);
    });
});
